\"\"\"Minimal OpenAI Responses API client using only the standard library.

Usage:
    export OPENAI_API_KEY=sk-...
    python openai_client.py \"Say hello\"

    from openai_client import OpenAIClient
    client = OpenAIClient()
    print(client.respond(\"Say hello\"))

Prompts are sent with "'``store=False`` by default so OpenAI does not retain the
response for later retrieval. The API key is read from the environment and is
never logged or written to disk.
"""

import argparse
import json
import os
import sys
import urllib.error
import urllib.request

DEFAULT_BASE_URL = "https://api.openai.com/v1"
DEFAULT_MODEL = "gpt-4.1-mini"


class OpenAIError(Exception):
    """Raised when the API returns an error or the request fails."""

    def __init__(self, message, status=None, body=None):
        super().__init__(message)
        self.status = status
        self.body = body


class OpenAIClient:
    def __init__(self, api_key=None, model=DEFAULT_MODEL, base_url=None, timeout=60):
        self.api_key = api_key or os.environ.get("OPENAI_API_KEY")
        if not self.api_key:
            raise OpenAIError("OPENAI_API_KEY is not set and no api_key was given")
        self.model = model
        self.base_url = (base_url or os.environ.get("OPENAI_BASE_URL") or DEFAULT_BASE_URL).rstrip("/")
        self.timeout = timeout

    def create_response(self, prompt, model=None, instructions=None, store=False, **params):
        """POST /responses and return the parsed JSON body."""
        payload = {"model": model or self.model, "input": prompt, "store": store}
        if instructions:
            payload["instructions"] = instructions
        payload.update(params)

        request = urllib.request.Request(
            self.base_url + "/responses",
            data=json.dumps(payload).encode("utf-8"),
            method="POST",
            headers={
                "Authorization": "Bearer " + self.api_key,
                "Content-Type": "application/json",
            },
        )
        try:
            with urllib.request.urlopen(request, timeout=self.timeout) as response:
                return json.loads(response.read().decode("utf-8"))
        except urllib.error.HTTPError as error:
            body = error.read().decode("utf-8", errors="replace")
            try:
                message = json.loads(body)["error"]["message"]
            except (ValueError, KeyError, TypeError):
                message = body or error.reason
            raise OpenAIError("HTTP %d: %s" % (error.code, message), error.code, body) from None
        except urllib.error.URLError as error:
            raise OpenAIError("Request failed: %s" % error.reason) from None

    @staticmethod
    def extract_text(response):
        """Concatenate all output_text parts from a Responses API result."""
        parts = []
        for item in response.get("output", []):
            if item.get("type") != "message":
                continue
            for content in item.get("content", []):
                if content.get("type") == "output_text":
                    parts.append(content.get("text", ""))
        return "".join(parts)

    def respond(self, prompt, **kwargs):
        """Send a prompt and return the response text."""
        return self.extract_text(self.create_response(prompt, **kwargs))


def main(argv=None):
    parser = argparse.ArgumentParser(description="Send a prompt to the OpenAI Responses API.")
    parser.add_argument("prompt", nargs="?", help="Prompt text (reads stdin if omitted)")
    parser.add_argument("-m", "--model", default=DEFAULT_MODEL)
    parser.add_argument("-i", "--instructions", help="System/developer instructions")
    args = parser.parse_args(argv)

    prompt = args.prompt if args.prompt is not None else sys.stdin.read()
    if not prompt.strip():
        parser.error("empty prompt")

    try:
        client = OpenAIClient(model=args.model)
        print(client.respond(prompt, instructions=args.instructions))
    except OpenAIError as error:
        print("Error: %s" % error, file=sys.stderr)
        return 1
    return 0


if __name__ == "__main__":
    sys.exit(main())
